<?php
$user = $user ?? [];
$statusMap = ['active' => ['class' => 'badge-success', 'label' => 'Active'], 'inactive' => ['class' => 'badge-neutral', 'label' => 'Inactive'], 'suspended' => ['class' => 'badge-danger', 'label' => 'Suspended']];
$roles = ['organization_admin' => 'Organization Admin', 'branch_manager' => 'Branch Manager', 'receptionist' => 'Receptionist'];
$status = $statusMap[$user['status'] ?? 'active'] ?? $statusMap['active'];
$roleLabel = $roles[$user['role'] ?? ''] ?? ucwords(str_replace('_', ' ', $user['role'] ?? '—'));
?>
<div class="breadcrumb"><a href="<?= site_url('admin/staff') ?>">Staff directory</a><span class="breadcrumb__sep">/</span><span><?= esc($user['name'] ?? 'Staff account') ?></span></div>
<div class="staff-heading"><div class="staff-heading__identity"><div class="staff-avatar avatar"><?= esc(strtoupper(substr($user['name'] ?? '?', 0, 1))) ?></div><div><span class="eyebrow">Platform staff account</span><h1><?= esc($user['name'] ?? 'Staff member') ?></h1><p><?= esc($roleLabel) ?> at <?= esc($user['organization_name'] ?? 'Unassigned') ?></p></div></div><span class="badge <?= $status['class'] ?>"><span class="badge__dot"></span><?= $status['label'] ?></span></div>
<div class="staff-grid"><div class="staff-main">
<section class="staff-panel"><div class="staff-panel__header"><div><h2>Account overview</h2><p>Identity, assignment, and access information for this team member.</p></div><a href="<?= site_url('organizations/' . (int) $user['organization_id'] . '/users/' . (int) $user['id'] . '/edit') ?>" class="btn btn-secondary btn-sm">Edit details</a></div><dl class="detail-list"><div><dt>Full name</dt><dd><?= esc($user['name'] ?? '—') ?></dd></div><div><dt>Email address</dt><dd><?= esc($user['email'] ?? '—') ?></dd></div><div><dt>Phone number</dt><dd><?= esc($user['phone'] ?? '—') ?></dd></div><div><dt>Role</dt><dd><span class="badge badge-info"><?= esc($roleLabel) ?></span></dd></div><div><dt>Organization</dt><dd><?= esc($user['organization_name'] ?? 'Unassigned') ?></dd></div><div><dt>Location</dt><dd><?= esc($user['branch_name'] ?? 'All locations') ?></dd></div><div><dt>Last sign-in</dt><dd><?= !empty($user['last_login_at']) ? esc(date('d M Y, H:i', strtotime($user['last_login_at']))) : 'Never signed in' ?></dd></div><div><dt>Created</dt><dd><?= !empty($user['created_at']) ? esc(date('d M Y, H:i', strtotime($user['created_at']))) : '—' ?></dd></div></dl></section>
<section class="staff-panel"><div class="staff-panel__header"><div><h2>Access status</h2><p>Control whether this account can sign in to its organization workspace.</p></div></div><div class="account-status-actions"><form method="post" action="<?= site_url('admin/staff/' . (int) $user['id'] . '/status') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="active"><button class="btn btn-secondary" type="submit" <?= $user['status'] === 'active' ? 'disabled' : '' ?>>Activate account</button></form><form method="post" action="<?= site_url('admin/staff/' . (int) $user['id'] . '/status') ?>" data-confirm-status="suspend"><?= csrf_field() ?><input type="hidden" name="status" value="suspended"><button class="btn btn-secondary" type="submit" <?= $user['status'] === 'suspended' ? 'disabled' : '' ?>>Suspend account</button></form><form method="post" action="<?= site_url('admin/staff/' . (int) $user['id'] . '/status') ?>" data-confirm-status="deactivate"><?= csrf_field() ?><input type="hidden" name="status" value="inactive"><button class="btn btn-ghost" type="submit" <?= $user['status'] === 'inactive' ? 'disabled' : '' ?>>Deactivate</button></form></div></section>
</div><aside class="staff-aside"><div class="staff-action-card"><span class="eyebrow">Credential management</span><h2>Reset password</h2><p>Generate a one-time temporary password for this staff member. Share it through a secure channel.</p><form method="post" action="<?= site_url('admin/staff/' . (int) $user['id'] . '/reset-password') ?>" data-confirm-reset><?= csrf_field() ?><button type="submit" class="btn btn-primary btn-block">Generate temporary password</button></form><?php if ($temporaryPassword = session()->getFlashdata('temporary_password')): ?><div class="temporary-password"><span>Temporary password</span><strong><?= esc($temporaryPassword) ?></strong><small>This is shown once. Ask the staff member to change it after signing in.</small></div><?php endif; ?></div><div class="staff-warning"><strong>Administrative action</strong><p>Status changes take effect immediately and are recorded in the platform audit log.</p></div></aside></div>
<?= $this->endSection() ?>
