<?= $this->section('scripts') ?><script>
document.querySelectorAll('[data-confirm-status]').forEach(function(form){form.addEventListener('submit',function(event){if(!window.confirm('Are you sure you want to '+form.getAttribute('data-confirm-status')+' this account?')){event.preventDefault();}});});
